  mt([("taxi", "таксі"), ("tram", "трамвай"), ("underground", "метро"), ("plane", "літак")], "Міський і далекий транспорт."),
  mt([("boat", "човен"), ("motorbike", "мотоцикл"), ("bike", "велосипед"), ("train", "поїзд")], "Bike — велосипед, motorbike — мотоцикл."),
  liu("I go to work by tram.", "Прослухайте. Чим людина їздить на роботу?", ["Трамваєм", "Поїздом", "На метро"], "By tram."),
  liu("Let's take a taxi. It's late.", "Прослухайте. Що пропонує людина?", ["Узяти таксі", "Піти пішки", "Сісти на автобус"], "Take a taxi."),
  fb("We go to Spain ___ plane.", ["by", "on", "with"], "By plane."),
  fb("I take the ___ in London. It's fast.", ["underground", "boat", "motorbike"], "The underground — метро."),
  mc("Як правильно?", ["I go by taxi.", "I go by the taxi.", "I go with taxi."], "By taxi — без артикля."),
  mcu("Який транспорт літає?", ["plane", "tram", "boat"], "Plane — літак."),
  bs("Візьмімо таксі.", ["Let's", "take", "a", "taxi"], ["by", "the"], "Let's take a taxi."),
  tr("Я їжджу трамваєм.", ["I go by tram", "I take the tram"], "I go by tram."),
