  W("keep the change", "/ˌkiːp ðə ˈtʃeɪndʒ/", "phrase", "решти не треба", "Here's twenty. Keep the change.", "Ось двадцять. Решти не треба."),
  W("traffic", "/ˈtræfɪk/", "noun", "рух транспорту, затори", "There's a lot of traffic.", "На дорогах великий рух."),
  W("fast", "/fɑːst/", A, "швидкий, швидко", "The train is fast.", "Поїзд швидкий."),
